50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private final ClinicService clinicService;
58	
59	    private final OwnerMapper ownerMapper;
60	
61	    private final PetMapper petMapper;
62	
63	    private final VisitMapper visitMapper;
64	
65	    public OwnerRestControllerV1(ClinicService clinicService,
66	                                 OwnerMapper ownerMapper,
67	                                 PetMapper petMapper,
68	                                 VisitMapper visitMapper) {
69	        this.clinicService = clinicService;
70	        this.ownerMapper = ownerMapper;
71	        this.petMapper = petMapper;
72	        this.visitMapper = visitMapper;
73	    }
74	
75	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
76	    @Override
77	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
78	        Collection<Owner> owners;
79	        if (lastName != null) {
80	            owners = this.clinicService.findOwnerByLastName(lastName);
81	        } else {
82	            owners = this.clinicService.findAllOwners();
83	        }
84	        if (owners.isEmpty()) {
85	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
86	        }
87	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
93	        Owner owner = this.clinicService.findOwnerById(ownerId);
94	        if (owner == null) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
103	        HttpHeaders headers = new HttpHeaders();
104	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
105	        if (ownerAlreadyExists(owner) || emailAlreadyExists(owner)) {
106	            return new ResponseEntity<>(HttpStatus.CONFLICT);
107	        }
108	        this.clinicService.saveOwner(owner);
109	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
110	        headers.setLocation(UriComponentsBuilder.newInstance()
111	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
112	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
113	    }
114	
115	    /**
116	     * Determines whether an owner already exists using the same telephone number.
117	     * Comparison ignores letter case and surrounding or repeated whitespace.
118	     *
119	     * @param owner the candidate owner to check
120	     * @return {@code true} if any other owner with the same telephone is already stored
121	     */
122	    private boolean ownerAlreadyExists(Owner owner) {
123	        String telephone = normalize(owner.getTelephone());
124	        return this.clinicService.findAllOwners().stream()
125	            .anyMatch(existing -> Objects.equals(normalize(existing.getTelephone()), telephone));
126	    }
127	
128	    /**
129	     * Determines whether another owner already uses the same email address.
130	     * Owners without an email are ignored, so a missing email never conflicts.
131	     * Comparison ignores letter case and surrounding or repeated whitespace.
132	     *
133	     * @param owner the candidate owner to check
134	     * @return {@code true} if the candidate supplies an email already used by a stored owner
135	     */
136	    private boolean emailAlreadyExists(Owner owner) {
137	        String email = normalize(owner.getEmail());
138	        if (email == null || email.isEmpty()) {
139	            return false;
140	        }
141	        return this.clinicService.findAllOwners().stream()
142	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
143	    }
144	
145	    /**
146	     * Normalizes a value for duplicate detection so that comparisons ignore letter
147	     * case and surrounding or repeated whitespace. Leading and trailing whitespace is
148	     * trimmed, any run of internal whitespace is collapsed to a single space, and the
149	     * result is lower-cased. For example {@code "  john   smith "} and {@code "John Smith"}
150	     * both normalize to {@code "john smith"}.
151	     *
152	     * @param value the raw value, may be {@code null}
153	     * @return the normalized value, or {@code null} if {@code value} is {@code null}
154	     */
155	    private static String normalize(String value) {
156	        if (value == null) {
157	            return null;
158	        }
159	        return value.strip().replaceAll("\\s+", " ").toLowerCase();
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
165	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
166	        if (currentOwner == null) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        currentOwner.setAddress(ownerFieldsDto.getAddress());
170	        currentOwner.setCity(ownerFieldsDto.getCity());
171	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
172	        currentOwner.setLastName(ownerFieldsDto.getLastName());
173	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
174	        this.clinicService.saveOwner(currentOwner);
175	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Transactional
180	    @Override
181	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
182	        Owner owner = this.clinicService.findOwnerById(ownerId);
183	        if (owner == null) {
184	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	        }
186	        this.clinicService.deleteOwner(owner);
187	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
188	    }
189	
